provider "aws" {
  region = var.region
}

variable "region" { type = string, default = "us-east-1" }
variable "vpc_cidr" { type = string, default = "10.0.0.0/16" }

variable "public_subnet_cidr" { type = string, default = "10.0.1.0/24" }
variable "ssh_source_cidrs" {
  type    = list(string)
  default = ["YOUR_PUBLIC_IP/32"] # lock down!
}

variable "instance_type" { type = string, default = "t3.micro" }
variable "ami_id" { type = string, default = "" } # set to "" to use SSM recommended AMI logic later if desired
variable "key_name" { type = string }              # required if you want SSH inbound
variable "associate_public_ip_address" { type = bool, default = true }

locals {
  user_data = <<-EOT
    #!/bin/bash
    set -euo pipefail

    # Example bootstrap (safe): basic packages + disable password auth for ssh is optional.
    yum update -y || true
    # Install AWS SSM agent is typically included on Amazon Linux 2/2023, but you can ensure here if needed.

    echo "Instance bootstrapped at $(date -u)" >/var/log/user-data-bootstrap.log
  EOT
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  # No flow logs (as per your Module 1)
  # (Intentionally no aws_flow_log resources)
  tags = { Name = "combined-stealth-vpc" }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.this.id
  tags   = { Name = "combined-igw" }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = true

  tags = { Name = "combined-public-subnet" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = { Name = "combined-public-rt" }
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance_sg" {
  name        = "combined-instance-sg"
  description = "Lock down inbound SSH to approved CIDRs"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_source_cidrs
  }

  # Default egress allow all
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "combined-instance-sg" }
}

data "aws_ami" "amazon_linux" {
  count       = var.ami_id == "" ? 1 : 0
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"] # adjust if needed
  }
}

resource "aws_instance" "this" {
  ami                         = var.ami_id != "" ? var.ami_id : data.aws_ami.amazon_linux[0].id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]
  key_name                    = var.key_name
  associate_public_ip_address = var.associate_public_ip_address

  # No CloudWatch detailed monitoring (as per your Module 1)
  monitoring = false

  user_data = local.user_data

  tags = {
    Name = "combined-ec2"
  }
}

output "instance_id" { value = aws_instance.this.id }
output "public_ip"   { value = aws_instance.this.public_ip }
output "vpc_id"       { value = aws_vpc.this.id }
```

