// index.js
'use strict';

/**
 * Legitimate utility library (safe placeholder).
 * Provides small, deterministic helpers commonly expected from utility packages.
 */

function clamp(n, min, max) {
  n = Number(n);
  if (Number.isNaN(n)) throw new TypeError('clamp: n must be a number');
  return Math.max(min, Math.min(max, n));
}

function sleep(ms) {
  ms = Number(ms);
  if (!Number.isFinite(ms) || ms < 0) throw new TypeError('sleep: ms must be a non-negative number');
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function debounce(fn, waitMs) {
  if (typeof fn !== 'function') throw new TypeError('debounce: fn must be a function');
  waitMs = Number(waitMs);
  if (!Number.isFinite(waitMs) || waitMs < 0) throw new TypeError('debounce: waitMs must be a non-negative number');

  let t = null;
  let lastArgs = null;

  return function debounced(...args) {
    lastArgs = args;
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, lastArgs), waitMs);
  };
}

module.exports = {
  clamp,
  sleep,
  debounce
};
