## Safe test package: `cred-harvest-test` (benign behavior, high-risk signals)

### 1) `package.json`
```json
{
  "name": "cred-harvest-test",
  "version": "1.0.0",
  "description": "Benign test package that simulates suspicious postinstall behavior without credential theft.",
  "main": "index.js",
  "scripts": {
    "postinstall": "node postinstall.js"
  },
  "author": "test",
  "license": "MIT"
}
```

### 2) `index.js`
```js
console.log("cred-harvest-test: installed.");
```

### 3) `postinstall.js`
```js
'use strict';

/**
 * SAFE SIMULATION NOTES (for your detection validation):
 * - Runs from postinstall (common malware trigger)
 * - Uses obfuscation-like base64 decoding + dynamic function construction
 * - Reads a dummy “secret” file shipped inside the package (not user credentials)
 * - Optionally sends data to a local test server if LOG_PORT is set
 * - Does NOT access OS keychains, env vars, ~/.ssh, wallet files, metadata services, or real exfiltration endpoints
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

function b64(s) {
  return Buffer.from(s, 'base64').toString('utf8');
}

// Obfuscated strings (benign)
const parts = [
  'ZHVtbXlfc2VjcmV0LnR4dA==',              // dummy_secret.txt
  'VGVzdCBpbnN0YWxsIGRhdGE6',             // "Test install data:"
  'Li4u',                                   // filler
  'cG9zdGluc3RhbGw=',                      // "postinstall"
  'c2Vuc2luZyB0byBsb2NhbCBsb2c='            // "sending to local log"
];

// Build a harmless message using decoded pieces
const dummyFile = b64(parts[0]);
const prefix = b64(parts[1]);

// Dynamically create a function to exercise “suspicious dynamic execution” detection.
// The payload is harmless: it just builds a string.
const fn = new Function('a', 'b', 'return a + b;');

const packageDir = __dirname;
const dummyPath = path.join(packageDir, dummyFile);

// This “secret” is a file included with the package (dummy content only)
let dummyContent = '';
try {
  dummyContent = fs.readFileSync(dummyPath, 'utf8');
} catch (e) {
  dummyContent = '(missing dummy file)';
}

const payload = fn(prefix, `\n${dummyContent}\n(phase=${b64(parts[3])})`);

// Optional local logging (safe; controlled by your harness)
const port = process.env.LOG_PORT;
if (port) {
  const msg = JSON.stringify({
    package: 'cred-harvest-test',
    event: 'postinstall',
    length: payload.length
  });

  const req = http.request(
    {
      hostname: '127.0.0.1',
      port: Number(port),
      path: '/log',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(msg)
      }
    },
    (res) => {
      // consume response
      res.on('data', () => {});
      res.on('end', () => {});
    }
  );

  req.on('error', () => {});
  req.write(msg);
  req.end();
}

// Also write a harmless local marker file in the package directory
try {
  fs.writeFileSync(path.join(packageDir, 'install-marker.txt'), payload, { encoding: 'utf8' });
} catch (e) {
  // ignore
}
```

