## Option A (recommended): Cross-account S3 replication using IAM roles (no break-glass user duplication)

### What it does
- In the **source** account: configures S3 replication rules to replicate all objects to a **destination (DR) bucket** in the **DR account**.
- Uses a **dedicated replication role** with least privilege (not an admin user).
- Optionally enables versioning (required for replication of deletes/changes).

### Terraform skeleton (source account)
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "src" {}
data "aws_partition" "current" {}

variable "region" { type = string }
variable "source_bucket_name" { type = string }
variable "dr_bucket_arn" { type = string } # e.g. arn:aws:s3:::my-dr-bucket
variable "dr_account_id" { type = string }

# Bucket must have versioning enabled for replication.
resource "aws_s3_bucket_versioning" "source" {
  bucket = var.source_bucket_name
  versioning_configuration {
    status = "Enabled"
  }
}

# Replication role assumed by S3 in the source account
resource "aws_iam_role" "s3_replication" {
  name = "dr-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { Service = "s3.amazonaws.com" },
      Action = "sts:AssumeRole"
    }]
  })
}

# Least-privilege policy allowing replication to the destination bucket
resource "aws_iam_policy" "s3_replication" {
  name = "dr-s3-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid = "ReadSource",
        Effect = "Allow",
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ],
        Resource = "arn:aws:s3:::${var.source_bucket_name}"
      },
      {
        Sid = "ReadObjectVersions",
        Effect = "Allow",
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ],
        Resource = "arn:aws:s3:::${var.source_bucket_name}/*"
      },
      {
        Sid = "WriteToDestination",
        Effect = "Allow",
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ],
        Resource = var.dr_bucket_arn == "" ? "*" : "${trim(var.dr_bucket_arn, "/")}" # expects arn:aws:s3:::bucket
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# Destination bucket replication permissions are handled by the destination bucket policy.
# We'll add that in the DR account example below.

resource "aws_s3_bucket_replication_configuration" "replication" {
  bucket = var.source_bucket_name
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "dr-all-objects"
    status = "Enabled"

    filter {
      prefix = "" # all objects
    }

    delete_marker_replication {
      status = "Enabled"
    }

    existing_object_replication {
      status = "Enabled"
    }

    destination {
      bucket        = var.dr_bucket_arn
      storage_class = "STANDARD"

      # Replication time control / metrics omitted; add if required.
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach]
}
```

### Terraform skeleton (DR account: destination bucket policy + versioning)
In the **destination (DR)** account, you must allow the replication role (from the source account) to write.

```hcl
provider "aws" {
  region = var.region
}

variable "region" { type = string }
variable "dr_bucket_name" { type = string }
variable "source_replication_role_arn" { type = string } # role ARN created in source account

resource "aws_s3_bucket_versioning" "dr" {
  bucket = var.dr_bucket_name
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "allow_replication_role" {
  bucket = var.dr_bucket_name

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Sid = "AllowS3ReplicationRoleFromSource",
      Effect = "Allow",
      Principal = { AWS = [var.source_replication_role_arn] },
      Action = [
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags",
        "s3:ObjectOwnerOverrideToBucketOwner",
        "s3:GetBucketVersioning",
        "s3:ListBucket"
      ],
      Resource = [
        "arn:aws:s3:::${var.dr_bucket_name}",
        "arn:aws:s3:::${var.dr_bucket_name}/*"
      ]
    }]
  })
}
```

