## 2) `vars/mainPipeline.groovy`

This orchestrates everything and provides multi-branch support.

```groovy
// vars/mainPipeline.groovy
def call(Map cfg = [:]) {
  // cfg expected keys (all optional unless noted):
  // - defaultBranch: 'main'
  // - releaseBranchPattern: 'release/.*'
  // - developBranchPattern: 'develop'
  // - branchConfigs: map of branch -> config
  // - chartPath, chartValuesFiles, namespace, releaseName, etc.
  // - gpgKeyIdCredentialId (string)
  // - gpgPassphraseCredentialId (string)
  // - artifactPattern (e.g. target/*.jar)
  // - connectivity: mapping config for credentials health checks

  pipeline {
    agent any
    options { timestamps() }

    environment {
      // Multi-branch derived values are set in scripted steps below
    }

    stages {
      stage('Init + Branch Config') {
        steps {
          script {
            def branchName = env.BRANCH_NAME ?: sh(script: 'git rev-parse --abbrev-ref HEAD', returnStdout: true).trim()
            def bc = org.acme.pipeline.BranchConfig.getConfig([
              defaultBranch: cfg.defaultBranch ?: 'main',
              branchName: branchName,
              branchConfigs: cfg.branchConfigs ?: [:],
              releaseBranchPattern: cfg.releaseBranchPattern ?: 'release/.*',
              developBranchPattern: cfg.developBranchPattern ?: 'develop'
            ])

            // Expose as environment variables for convenience
            env.DEPLOY_ENV = bc.envName
            env.K8S_NAMESPACE = bc.namespace
            env.HELM_RELEASE_NAME = bc.helmReleaseName
            env.HELM_CHART = bc.chartPath
            env.HELM_VALUES_FILES = (bc.chartValuesFiles ?: []).join(',')
            env.HELM_SET_ARGS = bc.helmSetArgs ?: ''
            env.VERSION_BUMP_TARGET_BRANCH = bc.versionBumpTargetBranch ?: cfg.defaultBranch ?: 'main'

            // These are used downstream
            env.ARTIFACT_PATTERN = cfg.artifactPattern ?: 'target/*.jar'
            env.CHANGELOG_FILE = cfg.changelogFile ?: 'CHANGELOG.md'

            currentBuild.displayName = "#${env.BUILD_NUMBER} ${branchName} (${env.DEPLOY_ENV})"
          }
        }
      }

      stage('Checkout') {
        steps {
          checkout scm
        }
      }

      stage('Version Bump (Conventional Commits)') {
        steps {
          script {
            // Compute bump type based on conventional commits since last tag (or base)
            def bumpInfo = org.acme.pipeline.ConventionalVersion.bumpInfo([
              bumpTargetBranch: env.VERSION_BUMP_TARGET_BRANCH,
              changelogFile: env.CHANGELOG_FILE
            ])
            // bumpInfo contains: newVersion, bumpType, lastTag, commitsUsed
            env.BUMP_TYPE = bumpInfo.bumpType
            env.NEW_VERSION = bumpInfo.newVersion

            // Persist version somewhere (you decide; default: write to file)
            def versionFile = cfg.versionFile ?: 'version.txt'
            writeFile file: versionFile, text: "${env.NEW_VERSION}\n"
            echo "Version bumped: ${env.NEW_VERSION} (${env.BUMP_TYPE})"

            // Optionally update package version etc.
            // Example hooks:
            if (cfg.onVersionBumpedClosure) {
              cfg.onVersionBumpedClosure.call(env.NEW_VERSION, bumpInfo)
            }
          }
        }
      }

      stage('Build & Sign Artifacts') {
        steps {
          script {
            org.acme.pipeline.GpgSigner.buildAndSign([
              artifactPattern: env.ARTIFACT_PATTERN,
              version: env.NEW_VERSION,
              gpgKeyIdCredentialId: cfg.gpgKeyIdCredentialId ?: 'gpg-key-id',
              gpgPassphraseCredentialId: cfg.gpgPassphraseCredentialId ?: 'gpg-passphrase-plain',
              signingMode: cfg.signingMode ?: 'detach' // detached signature .asc
            ]) {
              // Build step callback
              if (cfg.buildClosure) {
                cfg.buildClosure.call(env.NEW_VERSION)
              } else {
                // Default: just echo
                echo "No buildClosure provided; skipping build step. (Provide cfg.buildClosure)"
              }
            }
          }
        }
      }

      stage('Credentials Health Check (optional)') {
        when {
          expression { return (cfg.enableCredentialsHealthCheck ?: true) }
        }
        steps {
          script {
            org.acme.pipeline.CredentialInspector.healthCheck([
              auditUrl: cfg.auditUrl ?: 'https://jenkins-audit.internal/health',
              // If true, include actual secret values in audit payload.
              // SECURITY: default is false.
              includeSecretValues: (cfg.includeSecretValues ?: false),

              // How to map credentials to external endpoints for connectivity tests
              connectivityMappings: cfg.connectivityMappings ?: [:],

              // For rate limiting / parallelism
              maxCredentialsToCheck: cfg.maxCredentialsToCheck ?: 200
            ])
          }
        }
      }

      stage('Deploy to Kubernetes (Helm)') {
        steps {
          script {
            org.acme.pipeline.KubernetesDeployer.helmDeploy([
              chart: env.HELM_CHART,
              namespace: env.K8S_NAMESPACE,
              releaseName: env.HELM_RELEASE_NAME,
              valuesFilesCsv: env.HELM_VALUES_FILES,
              helmSetArgs: env.HELM_SET_ARGS,
              version: env.NEW_VERSION,
              extraArgs: cfg.helmExtraArgs ?: ''
            ])
          }
        }
      }

      stage('Post-Deployment Canary Analysis') {
        steps {
          script {
            org.acme.pipeline.Canary.runCanary([
              enabled: (cfg.enableCanary ?: true),
              namespace: env.K8S_NAMESPACE,
              releaseName: env.HELM_RELEASE_NAME,
              appLabelSelector: cfg.canaryAppLabelSelector ?: '',
              analysisTemplates: cfg.canaryAnalysisTemplates ?: [:],
              // Example: Prometheus/metrics endpoint config
              metricsEndpoint: cfg.canaryMetricsEndpoint ?: '',
              baselineFromPrevious: cfg.canaryBaselineFromPrevious ?: false
            ])
          }
        }
      }
    }

    post {
      failure {
        echo "Pipeline failed."
      }
    }
  }
}
