## 3) `src/org/acme/pipeline/BranchConfig.groovy`

Multi-branch environment-specific configuration.

```groovy
// src/org/acme/pipeline/BranchConfig.groovy
package org.acme.pipeline

class BranchConfig implements Serializable {

  static Map getConfig(Map args) {
    def branchName = args.branchName ?: 'main'
    def defaultBranch = args.defaultBranch ?: 'main'
    def releasePattern = args.releaseBranchPattern ?: 'release/.*'
    def developPattern = args.developBranchPattern ?: 'develop'
    def branchConfigs = args.branchConfigs ?: [:]

    // Highest precedence: explicit branch override by exact name
    if (branchConfigs.containsKey(branchName)) {
      return normalize(branchConfigs[branchName] as Map)
    }

    // Next precedence: branchConfigs by pattern (key can be regex string)
    def patternMatch = branchConfigs.find { k, v ->
      try {
        return (k instanceof String) && (branchName ==~ k)
      } catch (e) {
        return false
      }
    }
    if (patternMatch) {
      return normalize(patternMatch.value as Map)
    }

