## `src/index.js` (main CLI entry point)

```js
#!/usr/bin/env node

/**
 * kube-toolkit CLI entry.
 * Provides subcommands for:
 * - cluster health monitoring
 * - pod log aggregation
 * - resource dashboards
 * - RBAC visualization
 * - network policy analysis
 * - Helm release management
 * - secret rotation automation with backups + DR sync
 */

const { Command } = require("commander");
const path = require("path");
const fs = require("fs-extra");

const program = new Command();

program
  .name("kube-toolkit")
  .description("Kubernetes CLI toolkit: health monitoring, logs, dashboards, RBAC, network policies, Helm, and secret rotation.")
  .version("1.0.0");

function requireJsonConfig(configPath) {
  if (!configPath) return null;
  const full = path.resolve(process.cwd(), configPath);
  if (!fs.existsSync(full)) {
    throw new Error(`Config file not found: ${full}`);
  }
  return fs.readJsonSync(full);
}

