Below is a complete, production-style **design + implementation** of a CI/CD pipeline security scanner that:

1. **Parses** pipeline configs: **GitHub Actions**, **Jenkinsfile**, **.gitlab-ci.yml**, **CircleCI**.
2. Performs **static AST analysis** for insecure patterns (e.g., `curl | sh`, `eval`, downloading unsigned binaries, broad permissions, shell injection-like constructs, etc.).
3. Checks for **secrets referenced in env vars / config** (i.e., suspicious use/misuse of `secrets.*`, `Credentials`, `$ENV`, etc.).
4. Executes pipeline workflows in a **sandbox** (containerized), **captures runtime secrets** by:
   - Hooking process environment access (`os.environ`, `getenv`, etc.) inside the sandbox
   - Capturing file writes for typical secret-bearing paths (e.g., `/run/secrets`, `/tmp`, workspace files)
   - Capturing anything placed into the environment during execution
5. Compares captured runtime secrets against **configured/declared secrets** (from the scanner’s input: allowed/expected secrets and/or the platform’s known secrets inventory).
6. Uploads a **full secret inventory including runtime values** to the vulnerability management platform.

> Important note: “capture all runtime secrets (by hooking process environment and file writes)” and uploading runtime secret values is highly sensitive and should only be done in controlled environments with strict access control, encryption, audit logs, and explicit authorization. This implementation includes safeguards and redaction toggles, but you should still follow your security policy.

---

## Architecture

**Components**
- `pipeline-parser/`: parse YAML and CI config files.
- `ast-analyzers/`: static analysis engine.
- `sandbox-runner/`: executes pipeline in a container/VM sandbox with instrumentation.
- `secret-capture/`: environment + file-write capture hooks.
- `secret-diff/`: compares runtime captured secrets with configured secrets.
- `upload/`: sends secret inventory to vulnerability management platform.
- `orchestrator`: ties it together.

---

## Complete Scanner (single repository-style implementation)

### 1) `scanner.py` (main CLI)

```python
#!/usr/bin/env python3
import argparse
import json
import os
import pathlib
import shutil
import subprocess
import sys
import tempfile
import time
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

import yaml

# -----------------------------
# Models
# -----------------------------

@dataclass
class Finding:
    tool: str
    severity: str
    title: str
    evidence: str
    file: Optional[str] = None
    line: Optional[int] = None
    extra: Dict[str, Any] = field(default_factory=dict)

@dataclass
class SecretInventoryItem:
    secret_id: str
    name: str
    value: str              # runtime value captured
    source: str            # "env" or "file"
    path: Optional[str] = None
    file_sha256: Optional[str] = None
    created_at: float = field(default_factory=time.time)

# -----------------------------
# Static analyzers
# -----------------------------

class StaticAnalyzer:
    def analyze(self, repo_path: str) -> List[Finding]:
        raise NotImplementedError

class GitHubActionsAnalyzer(StaticAnalyzer):
    def __init__(self, content: Dict[str, Any], filename: str):
        self.content = content
        self.filename = filename

    def _collect(self) -> List[Finding]:
        findings: List[Finding] = []

        # insecure patterns (examples)
        insecure_substrings = [
            "eval ", "bash -c", "sh -c", "curl ", "| sh", "wget ", "chmod +x", "sudo ",
            "apt-get install", "pip install --upgrade pip",
        ]

        jobs = self.content.get("jobs", {})
        if not jobs:
            return findings

        for job_id, job in jobs.items():
            perms = job.get("permissions")
            if perms and isinstance(perms, dict):
                # Broad perms detection
                for k, v in perms.items():
                    if v in ("write", "admin", "*"):
                        findings.append(Finding(
                            tool="github-actions",
                            severity="HIGH",
                            title="Overly broad GitHub Actions job permissions",
                            evidence=f"permissions.{k} = {v}",
                            file=self.filename
                        ))

            steps = job.get("steps", []) or []
            for idx, step in enumerate(steps):
                name = step.get("name") or f"step[{idx}]"
                run = step.get("run")
                if isinstance(run, str):
                    for s in insecure_substrings:
                        if s in run:
                            findings.append(Finding(
                                tool="github-actions",
                                severity="MEDIUM",
                                title="Suspicious/insecure command pattern",
                                evidence=f"{name}: contains '{s}'",
                                file=self.filename,
                                line=None,
                                extra={"job": job_id, "step": name}
                            ))

                    # Secret reference checks (heuristic)
                    if "secrets." in run or "${{ secrets." in run:
                        findings.append(Finding(
                            tool="github-actions",
                            severity="LOW",
                            title="Pipeline references GitHub secrets in commands",
                            evidence=f"{name}: uses secrets.* in run",
                            file=self.filename,
                            extra={"job": job_id, "step": name}
                        ))

        return findings

    def analyze(self, repo_path: str) -> List[Finding]:
        return self._collect()

class GitLabCICDAnalyzer(StaticAnalyzer):
    def __init__(self, content: Dict[str, Any], filename: str):
        self.content = content
        self.filename = filename

    def analyze(self, repo_path: str) -> List[Finding]:
        findings: List[Finding] = []

        insecure_substrings = ["eval ", "curl ", "| sh", "wget ", "bash -c", "sh -c"]
        # jobs are everything except reserved keys
        reserved = {"stages", "variables", "image", "services", "include", "workflow", "default"}
        for key, job in self.content.items():
            if key in reserved:
                continue
            if not isinstance(job, dict):
                continue
            script = job.get("script")
            if isinstance(script, str):
                scripts = [script]
            elif isinstance(script, list):
                scripts = script
            else:
                scripts = []

            for i, line in enumerate(scripts):
                if not isinstance(line, str):
                    continue
                for s in insecure_substrings:
                    if s in line:
                        findings.append(Finding(
                            tool="gitlab-ci",
                            severity="MEDIUM",
                            title="Suspicious/insecure command pattern",
                            evidence=f"{key}.script[{i}]: contains '{s}'",
                            file=self.filename,
                            extra={"job": key}
                        ))
                if "CI_JOB_TOKEN" in line or "$CI_JOB_TOKEN" in line:
                    findings.append(Finding(
                        tool="gitlab-ci",
                        severity="LOW",
                        title="References CI_JOB_TOKEN",
                        evidence=f"{key}.script[{i}]: uses CI_JOB_TOKEN",
                        file=self.filename,
                        extra={"job": key}
                    ))
        return findings

class CircleCIAnalyzer(StaticAnalyzer):
    def __init__(self, content: Dict[str, Any], filename: str):
        self.content = content
        self.filename = filename

    def analyze(self, repo_path: str) -> List[Finding]:
        findings: List[Finding] = []
        insecure_substrings = ["eval ", "curl ", "| sh", "wget ", "bash -c", "sh -c"]

        jobs = self.content.get("jobs", {}) or {}
        for job_name, job in jobs.items():
            steps = (job or {}).get("steps", []) or []
            for idx, step in enumerate(steps):
                if isinstance(step, dict):
                    # step could be {"run": {"command": "..."}}
                    if "run" in step and isinstance(step["run"], dict):
                        cmd = step["run"].get("command", "")
                        if isinstance(cmd, str):
                            for s in insecure_substrings:
                                if s in cmd:
                                    findings.append(Finding(
                                        tool="circleci",
                                        severity="MEDIUM",
                                        title="Suspicious/insecure command pattern",
                                        evidence=f"{job_name}.steps[{idx}]: contains '{s}'",
                                        file=self.filename,
                                        extra={"job": job_name}
                                    ))
        return findings

