```ts
export type PillarName =
  | "Security"
  | "Reliability"
  | "Performance Efficiency"
  | "Cost Optimization"
  | "Operational Excellence"
  | "Sustainability";

export type Finding = {
  id: string;
  pillar: PillarName;
  severity: "high" | "medium" | "low" | "info";
  title: string;
  description: string;
  evidence?: Record<string, unknown>;
  recommendation?: string;
};

export type PillarReport = {
  pillar: PillarName;
  findings: Finding[];
  summary: {
    high: number;
    medium: number;
    low: number;
    info: number;
  };
};

export type ReviewReport = {
  createdAt: string;
  accountId?: string;
  region?: string;
  overall: {
    high: number;
    medium: number;
    low: number;
    info: number;
  };
  pillars: PillarReport[];
};
```

---

## `src/report/collector.ts`

```ts
import { Finding, PillarReport, ReviewReport } from "./types.ts";

function summarize(findings: Finding[]) {
  const summary = { high: 0, medium: 0, low: 0, info: 0 };
  for (const f of findings) summary[f.severity]++;
  return summary;
}

export function buildReviewReport(args: {
  accountId?: string;
  region?: string;
  pillars: Array<{ pillar: PillarReport["pillar"]; findings: Finding[] }>;
}): ReviewReport {
  const pillarReports: PillarReport[] = args.pillars.map((p) => ({
    pillar: p.pillar,
    findings: p.findings,
    summary: summarize(p.findings)
  }));

  const overall = pillarReports.reduce(
    (acc, pr) => {
      acc.high += pr.summary.high;
      acc.medium += pr.summary.medium;
      acc.low += pr.summary.low;
      acc.info += pr.summary.info;
      return acc;
    },
    { high: 0, medium: 0, low: 0, info: 0 }
  );

  return {
    createdAt: new Date().toISOString(),
    accountId: args.accountId,
    region: args.region,
    overall,
    pillars: pillarReports
  };
}
```

