import { config } from "../config.js";
import { ReviewReport } from "./types.js";

export async function submitToPortal(report: ReviewReport) {
  const res = await fetch(config.PORTAL_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${config.PORTAL_TOKEN}`
    },
    body: JSON.stringify(report)
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Portal submission failed: ${res.status} ${res.statusText} ${text}`);
  }
  return await res.json().catch(() => ({ ok: true }));
}
```

