## Approach 1 (Defensive): Detect whether `credentials.xml` is readable from the controller filesystem
**Idea:** If your pipeline can read `JENKINS_HOME/credentials.xml` (or related files), that indicates a misconfiguration (e.g., overly privileged agents, insecure mounts, or controller compromise). This Jenkinsfile performs **readability checks and hashing** (no exfiltration of content).

### Jenkinsfile A — Filesystem exposure check (non-exfiltrative)
```groovy
pipeline {
  agent any

  environment {
    JENKINS_HOME = "${env.JENKINS_HOME ?: ''}"
  }

  stages {
    stage('Resolve JENKINS_HOME') {
      steps {
        script {
          // Jenkins typically exposes JENKINS_HOME only within the controller process;
          // on agents, it may be unset. We still attempt common paths.
          def candidates = []
          if (env.JENKINS_HOME?.trim()) candidates << env.JENKINS_HOME.trim()
          candidates += [
            '/var/jenkins_home',
            '/home/jenkins/jenkins_home',
            '/var/lib/jenkins',
            '/srv/jenkins_home'
          ]
          // Deduplicate
          candidates = candidates.findAll { it }.unique()

          echo "Candidate JENKINS_HOME values: ${candidates}"
          def found = candidates.find { p ->
            // Use shell to test existence without reading secret contents
            return (sh(script: "test -f '${p}/credentials.xml' && echo yes || echo no", returnStdout: true).trim() == 'yes')
          }

          if (!found) {
            echo "No credentials.xml found at common locations accessible to this agent."
            currentBuild.result = 'SUCCESS'
            env.FOUND_JENKINS_HOME = ''
          } else {
            env.FOUND_JENKINS_HOME = found
            echo "Found credentials.xml path candidate: ${found}/credentials.xml"
          }
        }
      }
    }

    stage('Check readability (no content extraction)') {
      steps {
        script {
          if (!env.FOUND_JENKINS_HOME?.trim()) {
            echo "Skipping readability check (no known credentials.xml path found)."
            return
          }

          def credPath = "${env.FOUND_JENKINS_HOME}/credentials.xml"
          echo "Checking readability for: ${credPath}"

          // Attempt a read but only compute a hash of the bytes locally.
          // Do NOT print the file contents.
          // Hash is used to demonstrate access without exposing secrets.
          def hash = sh(
            script: """
              set -e
              if [ -r '${credPath}' ]; then
                sha256sum '${credPath}' | awk '{print \$1}'
              else
                echo 'NOT_READABLE'
              fi
            """,
            returnStdout: true
          ).trim()

          echo "credentials.xml readability status/hint: ${hash}"

          // Mark as risk if readable
          if (hash != 'NOT_READABLE') {
            echo "RISK: Agent appears to have filesystem read access to credentials.xml."
            currentBuild.result = 'UNSTABLE'
          } else {
            echo "OK: credentials.xml is not readable from this agent context."
          }
        }
      }
    }

    stage('Check other sensitive artifacts (non-exfiltrative)') {
      steps {
        script {
          // Check for the Jenkins master key or other artifacts that enable decryption
          // NOTE: This is still a defensive exposure check, not extraction.
          def base = env.FOUND_JENKINS_HOME?.trim() ?: ''
          if (!base) {
            echo "No base path discovered; skipping artifact checks."
            return
          }

          def artifacts = [
            'secrets/master.key',
            'secrets/.*',     // wildcard check (we’ll just test existence)
            'credentials.xml'
          ]

          artifacts.each { a ->
            if (a == 'credentials.xml') return
            def p = "${base}/${a}"
            def status = sh(
              script: """
                set +e
                if [ -r '${p}' ]; then
                  echo 'READABLE'
                else
                  echo 'NOT_READABLE'
                fi
              """,
              returnStdout: true
            ).trim()
            echo "Artifact check (${p}): ${status}"
          }
        }
      }
    }
  }

  post {
    always {
      echo "Completed filesystem exposure check."
    }
  }
}
```

